// ============================================================
// Cosmos DB – EF Core 9 breaking-change fixes
// Apply these to your separate Cosmos DB project's DbContext.
// ============================================================

using Microsoft.EntityFrameworkCore;
using Microsoft.Azure.Cosmos;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "MyDatabase",
            cosmosOptions =>
            {
                // FIX 2 (below): EF Core 9 disallows synchronous Cosmos I/O
                // by default.  If you have sync queries (e.g. .ToList(),
                // .First(), .SaveChanges()) that cannot be converted to async
                // right away, enable the compatibility flag:
                cosmosOptions.AllowSynchronousIO();
            });
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // FIX 1: EF Core 9 changed the default discriminator property
        // from "Discriminator" to "$type".  Existing documents already
        // store "Discriminator", so we must keep the old name to avoid
        // a runtime mismatch / empty query results.
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasDiscriminator<string>("Discriminator");
        });

        // Repeat for every entity that lives in a shared Cosmos container
        // and already has documents with the "Discriminator" property.
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

